options.getOption:
const frame = context.panel.data.series[0];
const field = (name) => frame?.fields.find((item) => item.name === name);
if (!field('Stage')) {
  return {};
}

const theme = context.grafana.theme;
const text = theme.colors.text.secondary;
const days = Array.from(field('Day').values);
const clocks = Array.from(field('Clock').values);
const stages = Array.from(field('Stage').values);
const sampleMs = 5 * 60 * 1000;
const stageNames = ['Deep', 'Light', 'REM', 'Awake'];
const stageColors = ['dark-blue', 'blue', 'purple', 'light-red'].map((name) => theme.visualization.getColorByName(name));
const nights = [...new Set(days)].sort((a, b) => a - b);
const nightIndex = new Map(nights.map((day, index) => [day, index]));
const nightLabel = (day) => new Date(day).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
const clockLabel = (ms) => new Date(ms).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });

// Each 5-minute sample is one rectangle, centered in the column of its night.
const renderItem = (params, api) => {
  const start = api.coord([api.value(0), api.value(1)]);
  const end = api.coord([api.value(0), api.value(2)]);
  const width = api.size([1, 0])[0] * 0.8;
  return {
    type: 'rect',
    shape: { x: start[0] - width / 2, y: end[1], width, height: start[1] - end[1] },
    style: { fill: api.visual('color') },
  };
};

const series = stageNames.map((name, stage) => ({
  name,
  type: 'custom',
  renderItem,
  itemStyle: { color: stageColors[stage] },
  encode: { x: 0, y: [1, 2] },
  data: clocks.flatMap((clock, index) =>
    stages[index] === stage ? [[nightIndex.get(days[index]), clock, clock + sampleMs]] : []
  ),
}));

return {
  backgroundColor: 'transparent',
  legend: { bottom: 0, textStyle: { color: text } },
  tooltip: {
    formatter: (item) =>
      `${nightLabel(nights[item.value[0]])}<br/>${item.seriesName}: ${clockLabel(item.value[1])} to ${clockLabel(item.value[2])}`,
  },
  grid: { left: 8, right: 8, top: 8, bottom: 32, containLabel: true },
  xAxis: { type: 'category', data: nights.map(nightLabel), axisLabel: { color: text } },
  yAxis: {
    type: 'time',
    min: 'dataMin',
    max: 'dataMax',
    axisLabel: { color: text, formatter: '{HH}:{mm}' },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  series,
};
